window.CHAPTERS = [{"number": 1, "title": "Kotlin · Cơ bản", "questions": [{"id": "20231-1-22", "text": "The 'when' statement in Kotlin is similar to which statement in other programming\nlanguages?", "type": "single", "options": [{"id": "A", "text": "continue"}, {"id": "B", "text": "break"}, {"id": "C", "text": "switch"}, {"id": "D", "text": "if"}], "answers": ["C"], "source": {"term": "20231", "pages": [7], "number": 22, "code": "76c978"}, "plain": true, "explanation": "when là cấu trúc phân nhánh gần với switch trong Java, nhưng mạnh hơn: có thể kiểm tra khoảng, kiểu và dùng như biểu thức trả về giá trị. Nó không tự rơi xuống nhánh tiếp theo như switch kiểu cũ; không cần break để kết thúc mỗi nhánh.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Điều khiển luồng"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [19], "number": 18, "code": "1e1bf6"}, {"term": "20231", "pages": [33], "number": 18, "code": "22d19e"}, {"term": "20231", "pages": [51, 52], "number": 35, "code": "3032b0"}, {"term": "20241", "pages": [2], "number": 15}]}, {"id": "20241-1-8", "text": "Trong Kotlin, dấu chấm phẩy (;) được sử dụng trong trường hợp nào?", "type": "single", "options": [{"id": "A", "text": "Kết thúc mỗi dòng lệnh"}, {"id": "B", "text": "Kết thúc mỗi câu lệnh"}, {"id": "C", "text": "Ngăn cách các câu lệnh trên cùng một dòng"}, {"id": "D", "text": "Kotlin không sử dụng dấu chấm phẩy"}], "answers": ["C"], "source": {"term": "20241", "pages": [1], "number": 8}, "plain": true, "explanation": "Kotlin thường không cần dấu chấm phẩy cuối dòng; dấu ; dùng để phân tách nhiều câu lệnh viết trên cùng một dòng. Ví dụ val a = 1; println(a). Đây là lựa chọn phù hợp nhất của đề; không suy ra Kotlin cấm dấu ; cuối câu lệnh. Bản bị cắt mất lựa chọn đúng không được chấm.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [10], "number": 16}]}, {"id": "20241-1-11", "text": "Từ khóa \"val\" được sử dụng với mục đích gì?", "type": "single", "options": [{"id": "A", "text": "Định nghĩa một biến không thay đổi được giá trị"}, {"id": "B", "text": "Định nghĩa một lớp"}, {"id": "C", "text": "Định nghĩa một biến có thể thay đổi giá trị"}, {"id": "D", "text": "Định nghĩa một hàm"}], "answers": ["A"], "source": {"term": "20241", "pages": [2], "number": 11}, "plain": true, "explanation": "val khai báo một tham chiếu chỉ được gán một lần; var cho phép gán lại. Điều này không đồng nghĩa đối tượng mà val trỏ tới luôn bất biến: val list = mutableListOf(1) vẫn cho phép list.add(2). Trong câu hỏi nhập môn, chọn phương án biến không gán lại giá trị.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [5, 6], "number": 12}, {"term": "20241", "pages": [10], "number": 10}, {"term": "20241", "pages": [11], "number": 1}]}, {"id": "20241-2-4", "text": "Phương án nào được sử dụng để tạo và khai báo các giá trị của mảng trong Kotlin?", "type": "single", "options": [{"id": "A", "text": "val a = {1, 2, 3, 4, 5}"}, {"id": "B", "text": "val a = [1, 2, 3, 4, 5]"}, {"id": "C", "text": "val a = array(1, 2, 3, 4, 5)"}, {"id": "D", "text": "val a = arrayOf(1, 2, 3, 4, 5)"}], "answers": ["D"], "source": {"term": "20241", "pages": [4], "number": 4}, "plain": true, "explanation": "arrayOf(1, 2, 3, 4, 5) tạo Array<Int> và khởi tạo các phần tử. Dấu [ ] dùng khi truy cập phần tử, không dùng trực tiếp làm literal mảng kiểu JavaScript trong Kotlin. Với mảng số nguyên chuyên biệt có thể dùng intArrayOf(...).", "references": [{"url": "https://kotlinlang.org/docs/arrays.html", "title": "Kotlin · Mảng"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [12], "number": 17}]}, {"id": "20241-2-16", "text": "Trong Kotlin, giá trị nào sẽ được in ra màn hình sau khi đoạn chương trình sau được thực hiện?\nval i = 10\nprintln(\"${i++}\")", "type": "single", "options": [{"id": "A", "text": "Đoạn chương trình bị lỗi cú pháp"}, {"id": "B", "text": "10"}, {"id": "C", "text": "11"}, {"id": "D", "text": "$11"}], "answers": ["A"], "source": {"term": "20241", "pages": [5, 7], "number": 16}, "plain": true, "explanation": "i được khai báo bằng val nên không được gán lại. Toán tử i++ cần cập nhật i, vì vậy đoạn code không biên dịch dù nằm trong string template. Nếu dùng var i = 10 thì phép tăng hậu tố in 10 trước rồi mới tăng i thành 11.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-4-5", "text": "Trong Kotlin, câu lệnh nào được sử dụng để khai báo biến kiểu số thực float với giá trị khởi tạo là 3.14?", "type": "single", "options": [{"id": "A", "text": "val x = 3.14"}, {"id": "B", "text": "float x = 3.14"}, {"id": "C", "text": "double x = 3.14"}, {"id": "D", "text": "val x = 3.14f"}], "answers": ["D"], "source": {"term": "20241", "pages": [11], "number": 5}, "plain": true, "explanation": "3.14 mặc định là literal Double; thêm hậu tố f hoặc F để tạo Float, như val x = 3.14f. Kotlin không dùng cú pháp float x hoặc double x kiểu Java. Float có độ chính xác thấp hơn Double nên không chỉ khác tên kiểu.", "references": [{"url": "https://kotlinlang.org/docs/numbers.html", "title": "Kotlin · Kiểu số"}], "reviewedOn": "2026-11-10", "note": ""}]}, {"number": 2, "title": "Kotlin · Hàm", "questions": [{"id": "20231-1-5", "text": "What is the default return type of any functions defined in Kotlin?", "type": "single", "options": [{"id": "A", "text": "Unit"}, {"id": "B", "text": "Double"}, {"id": "C", "text": "void"}, {"id": "D", "text": "Int"}], "answers": ["A"], "source": {"term": "20231", "pages": [2], "number": 5, "code": "ba6075"}, "plain": true, "explanation": "Unit là kiểu trả về mặc định của hàm có thân khối khi không khai báo kiểu trả về, ví dụ fun log() { println(\"Hi\") }. Đề dùng từ “any” quá rộng: hàm thân biểu thức như fun twice(x: Int) = x * 2 được suy ra kiểu Int. Kotlin dùng Unit thay cho cách viết void của Java.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [27], "number": 45, "code": "d453f0"}, {"term": "20231", "pages": [29], "number": 6, "code": "4d1306"}, {"term": "20231", "pages": [52], "number": 38, "code": "cba607"}]}, {"id": "20231-1-34", "text": "What are lambdas in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A lambda is an expression that describes a function. But instead of declaring a named function, you declare a function that has no name"}, {"id": "B", "text": "A lambda is a Class type in Kotlin"}, {"id": "C", "text": "A lambda is an Interface in Kotlin"}, {"id": "D", "text": "A lambda is a Data Type in Kotlin"}], "answers": ["A"], "source": {"term": "20231", "pages": [10], "number": 34, "code": "3"}, "plain": true, "explanation": "Lambda là biểu thức mô tả một hàm không có tên, ví dụ { x: Int -> x * 2 }. Có thể lưu nó trong biến kiểu hàm hoặc truyền làm đối số cho hàm bậc cao. Khi chỉ có một tham số và suy ra được kiểu, Kotlin cho phép dùng tên ngầm định it.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [26], "number": 43, "code": "28779a"}, {"term": "20231", "pages": [39], "number": 39, "code": "ad4df3"}, {"term": "20231", "pages": [44], "number": 9, "code": "fdeбea"}]}, {"id": "20241-1-9", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nfun main() {\n    println(calc(6, 4))\n}\nfun calc(x: Int, y: Int) = x % y", "type": "single", "options": [{"id": "A", "text": "Đoạn chương trình bị lỗi cú pháp"}, {"id": "B", "text": "10"}, {"id": "C", "text": "2"}, {"id": "D", "text": "1"}], "answers": ["C"], "source": {"term": "20241", "pages": [2], "number": 9}, "plain": true, "explanation": "calc(6, 4) tính phần dư 6 % 4 bằng 2. Với thân biểu thức = x % y, Kotlin suy ra kiểu trả về Int nên việc không ghi : Int không phải lỗi. Không nhầm % với phép chia nguyên 6 / 4 cho kết quả 1.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-1", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nvar s = 0\nrepeat(5) { s += it }\nprintln(s)", "type": "single", "options": [{"id": "A", "text": "10"}, {"id": "B", "text": "Đoạn chương trình bị lỗi cú pháp"}, {"id": "C", "text": "15"}, {"id": "D", "text": "6"}], "answers": ["A"], "source": {"term": "20241", "pages": [3], "number": 1}, "plain": true, "explanation": "repeat(5) chạy lambda 5 lần với it lần lượt là 0, 1, 2, 3, 4. Vì s bắt đầu bằng 0 nên tổng là 0 + 1 + 2 + 3 + 4 = 10. Không dùng 1 đến 5, và biến s phải là var vì được cập nhật mỗi lượt.", "references": [{"url": "https://kotlinlang.org/api/core/kotlin-stdlib/kotlin/repeat.html", "title": "Kotlin · repeat"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [9], "number": 2}]}, {"id": "20241-3-4", "text": "Đoạn chương trình sau sẽ in ra kết quả như thế nào?\nfun main() {\n    process(\"SoICT\") { it.uppercase() }\n}\nfun process(s: String, method: (String) -> String) {\n    println(method(s).lowercase())\n}", "type": "single", "options": [{"id": "A", "text": "SoICT"}, {"id": "B", "text": "soict"}, {"id": "C", "text": "SOICT"}, {"id": "D", "text": "Đoạn chương trình bị lỗi cú pháp"}], "answers": ["B"], "source": {"term": "20241", "pages": [9], "number": 4}, "plain": true, "explanation": "Lambda { it.uppercase() } biến \"SoICT\" thành \"SOICT\". Hàm process nhận kết quả đó rồi gọi lowercase() trước khi println, nên kết quả cuối cùng là \"soict\". Đây là hàm bậc cao vì method có kiểu (String) -> String.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [11], "number": 7}]}, {"id": "20241-3-12", "text": "Đáp án nào là định nghĩa về lambda trong Kotlin?", "type": "single", "options": [{"id": "A", "text": "Là một kiểu dữ liệu"}, {"id": "B", "text": "Là một lớp"}, {"id": "C", "text": "Là một biểu thức mô tả một hàm không bao gồm tên hàm"}, {"id": "D", "text": "Là một giao diện (Interface)"}], "answers": ["C"], "source": {"term": "20241", "pages": [10], "number": 12}, "plain": true, "explanation": "Lambda là biểu thức mô tả một hàm không có tên, ví dụ { x: Int -> x * 2 }. Có thể lưu nó trong biến kiểu hàm hoặc truyền làm đối số cho hàm bậc cao. Khi chỉ có một tham số và suy ra được kiểu, Kotlin cho phép dùng tên ngầm định it.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Lambda"}], "reviewedOn": "2026-11-10", "note": ""}]}, {"number": 3, "title": "Kotlin · Lớp và đối tượng", "questions": [{"id": "20231-1-26", "text": "Which of the following are true about abstract classes?", "type": "multi", "options": [{"id": "A", "text": "They can be extended by subclasses and implementations can be provided for abstract members of the class."}, {"id": "B", "text": "They have an implementation for all of their properties and functions."}, {"id": "C", "text": "They may have abstract properties or abstract functions."}, {"id": "D", "text": "They can be instantiated"}, {"id": "E", "text": "They are not fully implemented and cannot be instantiated."}, {"id": "F", "text": "They need to be marked with the open keyword to be extended."}], "answers": ["A", "C"], "source": {"term": "20231", "pages": [8], "number": 26, "code": "716dd3"}, "note": "", "plain": true, "explanation": "Theo nghĩa chặt của các phát biểu, chọn các ý: lớp con có thể kế thừa và triển khai thành viên abstract; lớp abstract có thể khai báo thuộc tính hoặc hàm abstract. Lớp abstract không khởi tạo trực tiếp và tự cho phép kế thừa, không cần open. Phương án ghép “not fully implemented and cannot be instantiated” quá mạnh: một lớp abstract có thể không có thành viên abstract, nên phần “not fully implemented” không luôn đúng.", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10", "otherSources": [{"term": "20231", "pages": [17], "number": 7, "code": "85f45a"}, {"term": "20231", "pages": [45], "number": 12}]}, {"id": "20231-1-28", "text": "Fill in the blank\nThe ___ is called when you create an instance of a class.", "type": "fill", "options": [], "answers": [], "source": {"term": "20231", "pages": [9], "number": 28, "code": "7977ca"}, "fields": [["constructor"]], "plain": true, "explanation": "Constructor được dùng khi tạo instance của lớp và khởi tạo các giá trị cần thiết. Kotlin có primary constructor và có thể có secondary constructor; các khối init cũng chạy trong quá trình khởi tạo. Đây không phải lời gọi một phương thức Activity như onCreate().", "references": [{"url": "https://kotlinlang.org/docs/classes.html", "title": "Kotlin · Lớp"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [22], "number": 26, "code": "ccbe41"}, {"term": "20231", "pages": [37], "number": 33, "code": "fa"}, {"term": "20231", "pages": [47], "number": 19, "code": "23f10d"}]}, {"id": "20241-1-5", "text": "Trong Kotlin, từ khóa nào được sử dụng để mô tả một hàm hoặc một thuộc tính có thể được viết chồng?", "type": "single", "options": [{"id": "A", "text": "override"}, {"id": "B", "text": "open"}, {"id": "C", "text": "final"}, {"id": "D", "text": "abstract"}], "answers": ["B"], "source": {"term": "20241", "pages": [1], "number": 5}, "note": "", "plain": true, "explanation": "open đặt ở khai báo lớp cha để cho phép kế thừa hoặc ghi đè thành viên vốn final mặc định. override đặt ở khai báo lớp con đang thực hiện ghi đè. Thành viên abstract vốn đã cho phép override; trong lựa chọn của câu hỏi này, open là từ khóa thể hiện chủ đích “có thể được viết chồng”.", "references": [{"url": "https://kotlinlang.org/docs/inheritance.html", "title": "Kotlin · Kế thừa"}], "reviewedOn": "2026-11-10"}]}, {"number": 4, "title": "Android · Introduction và Compose Unit 1", "questions": [{"id": "20231-1-1", "text": "The res folder does not include which following resources?", "type": "single", "options": [{"id": "A", "text": "file to define dependence libraries used in project"}, {"id": "B", "text": "file to define strings, colors used in project"}, {"id": "C", "text": "file to define demensions used in project"}, {"id": "D", "text": "file to define the menu structure used in project"}], "answers": ["A"], "source": {"term": "20231", "pages": [1], "number": 1, "code": "c8998a"}, "plain": true, "explanation": "res chứa layout, drawable, menu và các giá trị như strings, colors, dimens. Thư viện phụ thuộc được khai báo trong cấu hình Gradle của module, không phải một tài nguyên trong res.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}, {"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [26], "number": 42, "code": "b3debb"}, {"term": "20241", "pages": [12], "number": 19}]}, {"id": "20231-1-14", "text": "Which is a possible way/language to develop Android application?", "type": "multi", "options": [{"id": "A", "text": "Native approach: Java/Kotlin"}, {"id": "B", "text": "Web-based approach"}, {"id": "C", "text": "Universal Windows Platform (UWP) approach"}, {"id": "D", "text": "Object C"}, {"id": "E", "text": "Flutter"}], "answers": ["A", "B", "E"], "source": {"term": "20231", "pages": [4, 5], "number": 14, "code": "0af446"}, "plain": true, "explanation": "Java/Kotlin là hướng native thông dụng; giao diện web có thể được đóng gói hoặc tích hợp qua WebView; Flutter cũng hỗ trợ xuất ứng dụng Android. UWP là nền tảng của Microsoft, còn Objective-C không phải lựa chọn Android native được hỏi ở đây. Các phương án đúng mô tả nhiều hướng phát triển, không chỉ một ngôn ngữ.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}, {"url": "https://developer.android.com/develop/ui/views/layout/webapps/webview", "title": "WebView"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [16], "number": 6, "code": "7df36e"}, {"term": "20231", "pages": [36, 37], "number": 30, "code": "fbc87"}, {"term": "20231", "pages": [53], "number": 39, "code": "fcfdf5"}]}, {"id": "20231-1-32", "text": "Where to configure the home activity - the first activity to be run in your application?", "type": "single", "options": [{"id": "A", "text": "in the AndroidManifest.xml"}, {"id": "B", "text": "in the project level gradle file"}, {"id": "C", "text": "in the MainActivity.kt"}, {"id": "D", "text": "in the module level gradle file"}], "answers": ["A"], "source": {"term": "20231", "pages": [10], "number": 32, "code": "f2e"}, "plain": true, "explanation": "Activity khởi chạy từ biểu tượng ứng dụng được khai báo trong AndroidManifest.xml với intent-filter kết hợp android.intent.action.MAIN và android.intent.category.LAUNCHER. MainActivity.kt chứa mã thực thi, còn Gradle cấu hình build; chúng không thay thế khai báo launcher component trong manifest.", "references": [{"url": "https://developer.android.com/guide/components/intents-filters", "title": "Intent và intent filter"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [26], "number": 44, "code": "a5ec76"}, {"term": "20231", "pages": [37], "number": 31, "code": "2bcb"}, {"term": "20231", "pages": [44], "number": 8}]}, {"id": "20231-1-33", "text": "What is the language to program Android natively (select all correct answers)?", "type": "multi", "options": [{"id": "A", "text": "Java"}, {"id": "B", "text": "HTML, CSS, Javascript"}, {"id": "C", "text": "Kotlin"}, {"id": "D", "text": "C/C++"}], "answers": ["A", "C", "D"], "source": {"term": "20231", "pages": [10], "number": 33, "code": "45"}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [21], "number": 24, "code": "d757ef"}, {"term": "20231", "pages": [35], "number": 25, "code": "becOd"}, {"term": "20231", "pages": [43], "number": 6, "code": "59a05d"}]}, {"id": "20231-1-36", "text": "Which of the following is true about Gradle?", "type": "multi", "options": [{"id": "A", "text": "Gradle is an automated build system used by Android Studio to build your apps."}, {"id": "B", "text": "Gradle handles installing your app on a device"}, {"id": "C", "text": "Your app's build.gradle file is written in XML."}, {"id": "D", "text": "You can configure Android-specific options for your project in your app's build. gradle file."}, {"id": "E", "text": "The gradle configuration for your project cannot change after you initially create the project."}], "answers": ["A", "B", "D"], "source": {"term": "20231", "pages": [11], "number": 36, "code": "5775e0"}, "plain": true, "explanation": "Gradle tự động hóa build Android và có các task như installDebug để cài bản debug lên thiết bị phù hợp. build.gradle dùng Groovy DSL; build.gradle.kts dùng Kotlin DSL, không phải XML. Cấu hình module chứa các tùy chọn Android và dependencies, và có thể chỉnh sửa sau khi tạo dự án.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [18], "number": 11, "code": "b0491d"}, {"term": "20231", "pages": [46], "number": 16, "code": "5775e0"}]}, {"id": "20231-1-39", "text": "Which of the following is not a challange for Android application development?", "type": "single", "options": [{"id": "A", "text": "The deverloper may have to use different development tools in different OS"}, {"id": "B", "text": "The application must have compatibility with several different versions of Android"}, {"id": "C", "text": "The application mus be designed for multiple resolutions"}, {"id": "D", "text": "Source code and user's data must be secured"}], "answers": ["A"], "source": {"term": "20231", "pages": [12], "number": 39, "code": "53c0b3"}, "plain": true, "explanation": "Android Studio có bản cho nhiều hệ điều hành máy tính; việc bắt buộc dùng các công cụ khác nhau theo hệ điều hành, hoặc chỉ được lập trình trên một hệ điều hành, không phải hạn chế Android trong đề. Tương thích phiên bản Android, kích thước/độ phân giải màn hình và bảo vệ dữ liệu đều là các vấn đề thực tế cần xử lý.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [19], "number": 15, "code": "d7c1b1"}, {"term": "20231", "pages": [53], "number": 41, "code": "c0b309"}]}, {"id": "20241-1-2", "text": "Phát biểu nào không phải là một thách thức khi lập trình ứng dụng trên nền tảng Android?", "type": "single", "options": [{"id": "A", "text": "Ứng dụng cần tương thích với các phiên bản hệ điều hành khác nhau."}, {"id": "B", "text": "Ứng dụng cần thiết kế phù hợp với nhiều độ phân giải khác nhau."}, {"id": "C", "text": "Lập trình viên chỉ sử dụng công cụ lập trình trên một hệ điều hành nhất định."}, {"id": "D", "text": "Mã nguồn và dữ liệu người dùng cần được bảo mật."}], "answers": ["C"], "source": {"term": "20241", "pages": [1], "number": 2}, "plain": true, "explanation": "Android Studio có bản cho nhiều hệ điều hành máy tính; việc bắt buộc dùng các công cụ khác nhau theo hệ điều hành, hoặc chỉ được lập trình trên một hệ điều hành, không phải hạn chế Android trong đề. Tương thích phiên bản Android, kích thước/độ phân giải màn hình và bảo vệ dữ liệu đều là các vấn đề thực tế cần xử lý.", "references": [{"url": "https://developer.android.com/studio/install", "title": "Cài Android Studio"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [5, 6], "number": 13}]}, {"id": "20241-1-4", "text": "Ký tự R trong \"R.layout.activity_main\" tham chiếu đến thành phần nào trong Android?", "type": "single", "options": [{"id": "A", "text": "Resource"}, {"id": "B", "text": "Room"}, {"id": "C", "text": "Receiver"}, {"id": "D", "text": "Runnable"}], "answers": ["A"], "source": {"term": "20241", "pages": [1], "number": 4}, "plain": true, "explanation": "R là lớp tài nguyên được công cụ build sinh tự động. R.layout.activity_main là ID của tài nguyên layout tên activity_main; R.string, R.drawable và R.id là các nhóm ID khác. R không phải Room, Receiver hay Runnable.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}]}, {"id": "20241-1-10", "text": "Ở cửa sổ Project trong phần mềm Android Studio, chức năng hiển thị nào chỉ liệt kê 4 thành phần cơ bản của một dự án (AndroidManifest, mã nguồn Kotlin, các thư mục tài nguyên, các file gradle)?", "type": "single", "options": [{"id": "A", "text": "Production"}, {"id": "B", "text": "Android"}, {"id": "C", "text": "Project Files"}, {"id": "D", "text": "Packages"}], "answers": ["B"], "source": {"term": "20241", "pages": [2], "number": 10}, "plain": true, "explanation": "Chế độ Android trong cửa sổ Project gom file theo các nhóm quen thuộc như manifests, mã nguồn, res và Gradle Scripts. Đây là cách hiển thị logic phục vụ lập trình Android, không phải cấu trúc thư mục vật lý nguyên bản như Project. Tên và cách nhóm có thể khác nhẹ theo phiên bản Android Studio.", "references": [{"url": "https://developer.android.com/develop/ui/views/layout/declaring-layout", "title": "Layout trong Android"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [12], "number": 15}]}, {"id": "20241-1-14", "text": "Tập tin cấu hình nào chứa thông tin phiên bản và các dependencies của ứng dụng?", "type": "single", "options": [{"id": "A", "text": "AndroidManifest.xml"}, {"id": "B", "text": "proguard-rules.pro"}, {"id": "C", "text": "build.gradle"}, {"id": "D", "text": "settings.gradle"}], "answers": ["C"], "source": {"term": "20241", "pages": [2], "number": 14}, "plain": true, "explanation": "File build.gradle của module, hoặc build.gradle.kts với Kotlin DSL, khai báo các cấu hình như versionCode/versionName và dependencies. AndroidManifest.xml mô tả component/quyền; proguard-rules.pro cấu hình thu gọn/làm rối. Dự án hiện đại còn có version catalog nên không nhất thiết mọi giá trị phiên bản đều viết trực tiếp trong một file.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-3", "text": "File strings.xml chứa các tài nguyên chuỗi ký tự nằm trong thư mục nào?", "type": "single", "options": [{"id": "A", "text": "res/strings"}, {"id": "B", "text": "res/xml"}, {"id": "C", "text": "res/drawable"}, {"id": "D", "text": "res/values"}], "answers": ["D"], "source": {"term": "20241", "pages": [3], "number": 3}, "plain": true, "explanation": "Chuỗi trong strings.xml được đặt trong res/values; bản dịch có thể đặt trong values-vi, values-en và các thư mục có qualifier khác. Tên file strings.xml là quy ước quen dùng, còn loại tài nguyên được nhận biết từ phần tử string trong XML. res/strings không phải thư mục tài nguyên chuỗi chuẩn.", "references": [{"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [12], "number": 11}]}, {"id": "20241-2-15", "text": "Phát biểu nào không đúng về Gradle trong Android Studio?", "type": "single", "options": [{"id": "A", "text": "Các cấu hình đặc thù của Android (ví dụ phiên bản SDK) liên quan đến ứng dụng được thiết lập trong file build.gradle."}, {"id": "B", "text": "File build.gradle được mô tả bằng ngôn ngữ XML."}, {"id": "C", "text": "Gradle là hệ thống tự động dịch ứng dụng được sử dụng trong Android Studio."}, {"id": "D", "text": "Gradle thực hiện việc cài đặt ứng dụng trên thiết bị."}], "answers": ["B"], "source": {"term": "20241", "pages": [5, 7], "number": 15}, "plain": true, "explanation": "Gradle tự động hóa build Android và có các task như installDebug để cài bản debug lên thiết bị phù hợp. build.gradle dùng Groovy DSL; build.gradle.kts dùng Kotlin DSL, không phải XML. Cấu hình module chứa các tùy chọn Android và dependencies, và có thể chỉnh sửa sau khi tạo dự án.", "references": [{"url": "https://developer.android.com/build", "title": "Cấu hình build Android"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-2-17", "text": "Công cụ nào trong Android Studio được sử dụng để quản lý phiên bản Android được sử dụng để lập trình?", "type": "single", "options": [{"id": "A", "text": "SDK Manager"}, {"id": "B", "text": "Project Structure"}, {"id": "C", "text": "Resource Manager"}, {"id": "D", "text": "Device Manager"}], "answers": ["A"], "source": {"term": "20241", "pages": [7, 8], "number": 17}, "plain": true, "explanation": "SDK Manager cài đặt và quản lý SDK Platforms, Build Tools và các công cụ Android. Device Manager quản lý thiết bị ảo, còn Project Structure cấu hình dự án/module. Có nhiều SDK được cài không tự thay compileSdk của dự án; giá trị đó vẫn nằm trong cấu hình build.", "references": [{"url": "https://developer.android.com/studio/intro/update#sdk-manager", "title": "SDK Manager"}], "reviewedOn": "2026-11-10", "note": ""}, {"id": "20241-3-19", "text": "Ngôn ngữ lập trình nào không được sử dụng để lập trình ứng dụng Android dạng native?", "type": "single", "options": [{"id": "A", "text": "C++"}, {"id": "B", "text": "Kotlin"}, {"id": "C", "text": "Java"}, {"id": "D", "text": "JavaScript"}], "answers": ["D"], "source": {"term": "20241", "pages": [10], "number": 19}, "plain": true, "explanation": "Java và Kotlin dùng cho mã Android thông thường; C/C++ có thể dùng qua Android NDK cho phần native. HTML/CSS/JavaScript chủ yếu là công nghệ web, không thuộc các ngôn ngữ native được phân loại trong đề. Một ứng dụng dùng framework JavaScript vẫn có thể chứa mã native, nhưng đó là hướng phát triển khác với câu hỏi này.", "references": [{"url": "https://developer.android.com/ndk/guides", "title": "Android NDK"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20241", "pages": [11], "number": 6}]}]}, {"number": 5, "title": "Compose Unit 3 · Launcher icons", "questions": [{"id": "20231-1-37", "text": "Which of the following statements about app icons are true?", "type": "multi", "options": [{"id": "A", "text": "It is sufficient to provide a single bitmap image of your app icon in your project to make it appear high quality on a range of Android devices."}, {"id": "B", "text": "mdpi, hdpi, xhdpi, xxhdpi, and xxxhdpi are density qualifiers for resource directories to indicate that these are resources to be used on devices with a specific screen density."}, {"id": "C", "text": "Adaptive icons are made up of a foreground and background layer, and an OEM mask will be applied on top of them."}, {"id": "D", "text": "Vector drawables only work for a certain screen density and should not be scaled."}], "answers": ["B", "C"], "source": {"term": "20231", "pages": [11], "number": 37, "code": "167926"}, "plain": true, "explanation": "Nhóm mật độ đúng là mdpi, hdpi, xhdpi, xxhdpi, xxxhdpi; “dpi” đứng riêng trong bản OCR là lỗi mất chữ x. Adaptive icon có các lớp foreground/background và có thể được launcher áp mặt nạ; thiết bị mới còn hỗ trợ lớp monochrome. Bitmap cần xét mật độ màn hình, còn vector có thể co giãn. Phương án đã được sửa lỗi OCR trước khi chấm các ý về mật độ và lớp adaptive icon.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}, {"url": "https://developer.android.com/guide/topics/resources/providing-resources", "title": "Android · Tài nguyên"}], "reviewedOn": "2026-11-10", "note": "", "otherSources": [{"term": "20231", "pages": [18], "number": 12, "code": "febc95"}, {"term": "20231", "pages": [40], "number": 43, "code": "08c62c"}, {"term": "20231", "pages": [46, 47], "number": 17, "code": "167926"}]}]}, {"number": 6, "title": "Google · Unit 1 · Pathway 1 · Intro to Programming", "questions": [{"id": "google-u1-p1-q1", "text": "Which of the following variable declarations is valid?", "type": "single", "options": [{"id": "A", "text": "var hello: Int? = \"\""}, {"id": "B", "text": "String \"hello\" = hello"}, {"id": "C", "text": "val hello = \"hello\""}, {"id": "D", "text": "hello: String = \"hello\""}], "answers": ["C"], "plain": true, "note": "", "explanation": "Khai báo cần có val hoặc var; Kotlin có thể suy ra kiểu từ vế phải. Ví dụ val hello = \"hello\" là String, còn var hello: Int? = \"\" sai vì gán chuỗi cho kiểu số nguyên nullable.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q2", "text": "It is considered best practice to declare a variable that will not change using var instead of val .", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Dùng val khi không cần gán lại để thể hiện ý định và giảm lỗi sửa biến ngoài dự kiến. val không làm đối tượng mutable trở thành immutable; nó chỉ ngăn đổi tham chiếu bằng phép gán.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q3", "text": "Which of the following are valid ways to update a variable?", "type": "multi", "options": [{"id": "A", "text": "total++"}, {"id": "B", "text": "total - 1"}, {"id": "C", "text": "total--"}, {"id": "D", "text": "total = total + 1"}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "Giả sử total là var kiểu số: total++ và total-- cập nhật biến, còn total = total + 1 gán giá trị mới. Biểu thức total - 1 chỉ tính một kết quả rồi bỏ đi nếu không sử dụng hoặc gán lại.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q4", "text": "In Kotlin, comments can be single or multi-line and are ignored by the compiler.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "// ghi chú đến hết dòng; /* ... */ có thể trải trên nhiều dòng và Kotlin còn hỗ trợ comment khối lồng nhau. Comment giúp giải thích ý định nhưng không trở thành câu lệnh được thực thi.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q5", "text": "Which of the following is not a data type in Kotlin?", "type": "single", "options": [{"id": "A", "text": "String"}, {"id": "B", "text": "Decimal"}, {"id": "C", "text": "Int"}, {"id": "D", "text": "Boolean"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Các kiểu số dựng sẵn gồm Byte, Short, Int, Long, Float, Double; Decimal không phải tên kiểu dựng sẵn. Nếu cần tính thập phân chính xác cho tiền tệ trên JVM có thể cân nhắc BigDecimal thay vì số thực nhị phân.", "references": [{"url": "https://kotlinlang.org/docs/numbers.html", "title": "Kotlin · Kiểu số"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q6", "text": "Float also represents a decimal, but is less precise than Double .", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Float dùng 32 bit còn Double dùng 64 bit, nên Float thường chỉ giữ khoảng 6–7 chữ số thập phân có nghĩa so với khoảng 15–16 của Double. Literal 3.14 mặc định là Double; 3.14f là Float.", "references": [{"url": "https://kotlinlang.org/docs/numbers.html", "title": "Kotlin · Kiểu số"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q7", "text": "In Kotlin, the entrypoint of a program is the ___.", "type": "single", "options": [{"id": "A", "text": "println() statement"}, {"id": "B", "text": "val variable"}, {"id": "C", "text": "main() function"}, {"id": "D", "text": "return statement"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Một chương trình Kotlin thông thường bắt đầu ở fun main() hoặc main(args: Array<String>). println chỉ là lời gọi in dữ liệu. Riêng ứng dụng Android có các điểm vào do framework quản lý, không viết main() làm Activity entrypoint.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q8", "text": "Which of the following are true about function return values?", "type": "multi", "options": [{"id": "A", "text": "If a function does not specify a return type, the return type is Unit ."}, {"id": "B", "text": "A return value can be stored in a variable."}, {"id": "C", "text": "Functions with a return type of Unit must include a return statement."}, {"id": "D", "text": "A return value's type must match the return type of a function."}], "answers": ["A", "B", "D"], "plain": true, "note": "", "explanation": "Ý “không khai báo kiểu trả về thì dùng Unit” của Google dùng ngữ cảnh hàm thân khối nhập môn, không phải quy tắc cho mọi hàm. Với fun twice(x: Int) = x * 2, Kotlin suy ra Int. Hàm Unit không bắt buộc viết return; giá trị trả về thông thường có thể được gán cho biến và phải đúng kiểu khai báo.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q9", "text": "Which of the following are true about functions?", "type": "multi", "options": [{"id": "A", "text": "Functions can take parameters, or variables as inputs."}, {"id": "B", "text": "Function parameters are required to have default arguments."}, {"id": "C", "text": "When calling a function with parameters, the values passed in are called arguments."}, {"id": "D", "text": "Breaking up your code into separate functions makes your code easier to maintain."}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "Parameter nằm trong khai báo hàm; argument là giá trị truyền ở lời gọi, như name trong fun greet(name: String) và \"Lan\" trong greet(\"Lan\"). Giá trị mặc định là tùy chọn. Chia nhỏ hàm theo trách nhiệm giúp đọc, kiểm thử và bảo trì.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q10", "text": "With named arguments, you can change the order in which you pass arguments into a function.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Khi gọi greet(age = 20, name = \"Lan\"), tên argument cho biết nó đi vào tham số nào nên thứ tự có thể thay đổi. Nếu trộn positional và named argument cần tuân thủ quy tắc Kotlin; tên phải khớp khai báo hàm.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 7, "title": "Google · Unit 1 · Pathway 2 · Set up Android Studio", "questions": [{"id": "google-u1-p2-q1", "text": "What does IDE stand for?", "type": "single", "options": [{"id": "A", "text": "Integrated Development Environment"}, {"id": "B", "text": "Independent Design Environment"}, {"id": "C", "text": "Ideal Developer Environment"}, {"id": "D", "text": "Intelligent Design Environment"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Integrated Development Environment là môi trường tích hợp sửa mã, điều hướng, build và debug. Android Studio là một IDE; Gradle là hệ thống build mà IDE dùng, không phải cùng một khái niệm.", "references": [{"url": "https://developer.android.com/studio/intro", "title": "Android Studio"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q2", "text": "Which of the following are advantages of using Android Studio?", "type": "multi", "options": [{"id": "A", "text": "It can help prevent typos and other mistakes in your code."}, {"id": "B", "text": "It comes with a virtual device called an emulator that can run your app."}, {"id": "C", "text": "It can show you a real-time preview of how your app will look on-screen while you code."}, {"id": "D", "text": "It can automatically translate your app into other languages."}], "answers": ["A", "B", "C"], "plain": true, "note": "", "explanation": "Code inspection và gợi ý hoàn thành giúp giảm lỗi; emulator hỗ trợ chạy thử; Compose Preview hỗ trợ xem UI. Android Studio không mặc nhiên dịch toàn bộ giao diện sang ngôn ngữ khác: lập trình viên vẫn cần quản lý tài nguyên bản dịch.", "references": [{"url": "https://developer.android.com/studio/intro", "title": "Android Studio"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q3", "text": "What is the purpose of using a virtual device, or emulator, in Android Studio?", "type": "single", "options": [{"id": "A", "text": "To show a variety of error messages to users"}, {"id": "B", "text": "To experiment with app code safely"}, {"id": "C", "text": "To test your app on a device without having that physical device"}, {"id": "D", "text": "To see what your app looks like in a web browser"}], "answers": ["C"], "plain": true, "note": "", "explanation": "AVD mô phỏng cấu hình máy, API Android và kích thước màn hình để cài/chạy ứng dụng. Nó không phải trình duyệt web và không thay thế hoàn toàn thử nghiệm thực tế về hiệu năng, cảm biến hay phần cứng.", "references": [{"url": "https://developer.android.com/studio/run/emulator", "title": "Android Emulator"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q4", "text": "In Android Studio, what is a project template good for?", "type": "multi", "options": [{"id": "A", "text": "It causes Android Studio to download files faster."}, {"id": "B", "text": "It makes getting started on building a new app faster."}, {"id": "C", "text": "It provides a structure that follows best practices."}, {"id": "D", "text": "It is the only way to build apps that can be previewed in Android Studio."}, {"id": "E", "text": "It makes building a new app less error-prone by pre-populating the project with some app code."}], "answers": ["B", "C", "E"], "plain": true, "note": "", "explanation": "Template sinh cấu trúc module, cấu hình build và mã mẫu để bắt đầu nhanh hơn, ít thiếu bước hơn. Nó không phải cách duy nhất để viết ứng dụng hoặc tạo preview; dự án có sẵn vẫn có thể thêm composable và @Preview.", "references": [{"url": "https://developer.android.com/studio/projects/create-project", "title": "Tạo dự án Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q5", "text": "How do you create a new project in Android Studio?", "type": "single", "options": [{"id": "A", "text": "A. Log out of Android Studio, and navigate to your project folder to find instructions."}, {"id": "B", "text": "B. If you have a project already open, select File > New > New Project from the Android Studio menu."}, {"id": "C", "text": "C. In the “Welcome to Android Studio” window, click “Start a new Android Studio project.”"}, {"id": "D", "text": "D. Create a new file on your computer, and title it “New Android Studio Project.\""}, {"id": "E", "text": "Both B and C are ways to create a new project in Android Studio."}, {"id": "F", "text": "None of the above"}], "answers": ["E"], "plain": true, "note": "", "explanation": "Có thể tạo dự án từ File → New → New Project khi đang mở IDE hoặc từ nút New Project ở màn hình Welcome. Nhãn nút có thể thay đổi theo bản Android Studio. Chỉ tạo một file tên “New Android Studio Project” không tạo ra dự án Android hợp lệ.", "references": [{"url": "https://developer.android.com/studio/projects/create-project", "title": "Tạo dự án Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q6", "text": "___ is a function that is used to define a layout in your app using Composable functions.", "type": "single", "options": [{"id": "A", "text": "ComponentActivity()"}, {"id": "B", "text": "onCreate()"}, {"id": "C", "text": "DefaultPreview()"}, {"id": "D", "text": "setContent()"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Trong ComponentActivity, setContent { ... } đặt nội dung UI Compose cho Activity. onCreate là callback vòng đời thường chứa lời gọi này, còn @Preview chỉ phục vụ công cụ xem trước. ComponentActivity là lớp, không phải hàm dựng nội dung thay cho setContent.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q7", "text": "A Compose function requires the @Composable annotation.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "@Composable đánh dấu hàm tham gia mô tả UI trong hệ Compose. Hàm có thể được chạy lại khi dữ liệu liên quan thay đổi, vì vậy không nên coi nó là lệnh vẽ chỉ chạy một lần. @Preview có vai trò khác và không thay thế @Composable.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}, "otherSources": [{"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}]}, {"id": "google-u1-p2-q9", "text": "Padding is an example of a ___", "type": "single", "options": [{"id": "A", "text": "Property"}, {"id": "B", "text": "Composable"}, {"id": "C", "text": "Attribute"}, {"id": "D", "text": "Modifier"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Modifier.padding(...) thay đổi khoảng cách quanh nội dung của composable. Thứ tự modifier có tác dụng: clickable().padding() có thể tạo vùng click khác padding().clickable(). Padding là modifier, không phải một composable riêng để bố trí các con.", "references": [{"url": "https://developer.android.com/develop/ui/compose/modifiers", "title": "Compose · Modifier"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 8, "title": "Google · Unit 1 · Pathway 3 · Build a basic layout", "questions": [{"id": "google-u1-p3-q1", "text": "What is Jetpack Compose?", "type": "single", "options": [{"id": "A", "text": "A Modern toolkit to develop Android UI"}, {"id": "B", "text": "Toolkit to design libraries"}, {"id": "C", "text": "Database Interface"}, {"id": "D", "text": "Plugin to build APK"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Compose là bộ công cụ UI Android theo hướng khai báo: mô tả giao diện tương ứng với state thay vì cập nhật từng View thủ công. Nó không phải một cơ sở dữ liệu hoặc plugin đóng gói APK.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q2", "text": "Composable functions are the basic building block of Compose.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Các composable nhỏ kết hợp thành cây UI lớn hơn và có thể tái sử dụng. Chúng là đơn vị mô tả giao diện, còn layout, modifier và state quyết định cách hiển thị cũng như thay đổi khi chạy.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q4", "text": "The basic standard layout elements in Compose are:", "type": "multi", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Row"}, {"id": "C", "text": "Text"}, {"id": "D", "text": "Box"}], "answers": ["A", "B", "D"], "plain": true, "note": "", "explanation": "Column xếp theo chiều dọc, Row theo chiều ngang và Box xếp chồng hoặc căn các con trong một vùng. Text là thành phần hiển thị chữ; nó không thuộc ba primitive layout đang được hỏi.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q5", "text": "What is the tool window for importing, creating, managing, and using resources in your app?", "type": "single", "options": [{"id": "A", "text": "Application Manager"}, {"id": "B", "text": "Resource Manager"}, {"id": "C", "text": "Resource Tool"}, {"id": "D", "text": "Layout Manager"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Resource Manager trong Android Studio giúp nhập và quản lý tài nguyên như drawable. Resource ID dùng trong mã nằm ở lớp R. Nó khác SDK Manager quản lý SDK và Device Manager quản lý thiết bị ảo.", "references": [{"url": "https://developer.android.com/guide/topics/resources/accessing-resources", "title": "Truy cập tài nguyên"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q7", "text": "Which function is used is to load a drawable image resource.", "type": "single", "options": [{"id": "A", "text": "The stringResource() function"}, {"id": "B", "text": "The painterResource() function"}, {"id": "C", "text": "The ImageResource() function"}, {"id": "D", "text": "The loadResource() function"}], "answers": ["B"], "plain": true, "note": "", "explanation": "painterResource(R.drawable.photo) tạo Painter từ drawable để dùng với Image. stringResource(...) nạp chuỗi. Ảnh từ mạng thường cần thư viện tải ảnh hoặc luồng xử lý khác, không truyền URL thay cho resource ID vào painterResource.", "references": [{"url": "https://developer.android.com/develop/ui/compose/graphics/images/loading", "title": "Compose · Nạp ảnh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q8", "text": "What is the function parameter used to add accessibility text, used by talkback?", "type": "single", "options": [{"id": "A", "text": "accessibilityText"}, {"id": "B", "text": "contentText"}, {"id": "C", "text": "accessibilityDescription"}, {"id": "D", "text": "contentDescription"}], "answers": ["D"], "plain": true, "note": "", "explanation": "contentDescription cung cấp mô tả ngữ nghĩa để trình đọc màn hình đọc thay cho ảnh/icon có ý nghĩa. Ảnh chỉ để trang trí thường đặt null để tránh đọc thừa. Mô tả nên nói chức năng hoặc thông tin, không chỉ lặp “hình ảnh”.", "references": [{"url": "https://developer.android.com/develop/ui/compose/accessibility/semantics", "title": "Compose · Accessibility"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q9", "text": "The Box layout stacks the UI elements on top of one another.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Các con trong Box có thể chồng lên nhau; con khai báo sau thường vẽ trên con trước nếu không có điều chỉnh zIndex. Dùng alignment hoặc Modifier.align để định vị trong vùng Box, thay vì mặc định coi Box là một hàng hay cột.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q10", "text": "What parameter is used to align the child element to the beginning of the parent?", "type": "single", "options": [{"id": "A", "text": "Alignment.End"}, {"id": "B", "text": "Alignment.Begin"}, {"id": "C", "text": "Alignment.Start"}, {"id": "D", "text": "Alignment.Top"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Start là cạnh bắt đầu theo layout direction: thường là trái với LTR và phải với RTL. Alignment.Start là căn theo chiều ngang trong API phù hợp; Alignment.Top là căn dọc, không cùng ý nghĩa.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}]}, {"number": 9, "title": "Google · Unit 2 · Pathway 1 · Kotlin fundamentals", "questions": [{"id": "google-u2-p1-q1", "text": "The following code will print \"Divisible by 5\" if number is equal to 25 .\n\nif (number % 10 == 0) {\n  println(\"Divisible by 10\")\n} else if (number == 5) {\n  println(\"Divisible by 5\")\n}", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Với 25, điều kiện 25 % 10 == 0 sai, rồi 25 == 5 cũng sai. Không có else nên không in dòng nào. Muốn kiểm tra “chia hết cho 5” phải dùng number % 5 == 0, không dùng number == 5.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Phân nhánh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q2", "text": "Which of the following conditions are satisfied when x = 5 ?", "type": "multi", "options": [{"id": "A", "text": "x == 5"}, {"id": "B", "text": "x in 1..5"}, {"id": "C", "text": "x is Int"}, {"id": "D", "text": "x % 5"}], "answers": ["A", "B", "C"], "plain": true, "note": "", "explanation": "x = 5 làm x == 5 đúng, khoảng 1..5 bao gồm cả hai đầu nên x in 1..5 đúng, và 5 có kiểu Int. x % 5 tạo số 0 chứ không phải điều kiện Boolean; muốn xét chia hết cần x % 5 == 0.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Phân nhánh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q3", "text": "Which is not a basic concept of object-oriented programming", "type": "single", "options": [{"id": "A", "text": "Abstraction"}, {"id": "B", "text": "Readability"}, {"id": "C", "text": "Inheritance"}, {"id": "D", "text": "Polymorphism"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Abstraction mô tả phần cốt lõi, inheritance cho phép kế thừa, polymorphism cho phép cùng giao diện có nhiều cách triển khai. Readability là tính dễ đọc của mã, rất hữu ích nhưng không phải một khái niệm OOP cơ bản trong nhóm lựa chọn.", "references": [{"url": "https://kotlinlang.org/docs/inheritance.html", "title": "Kotlin · Kế thừa"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q4", "text": "Which are the four visibility modifiers in Kotlin?", "type": "single", "options": [{"id": "A", "text": "public , private , protected , abstract"}, {"id": "B", "text": "static , override , internal , external"}, {"id": "C", "text": "private , protected , public , internal"}, {"id": "D", "text": "public , protected , static , internal"}], "answers": ["C"], "plain": true, "note": "", "explanation": "public cho phép truy cập rộng; private giới hạn theo phạm vi khai báo; protected áp dụng cho thành viên trong lớp và lớp con; internal giới hạn theo module. abstract và override không phải visibility modifier.", "references": [{"url": "https://kotlinlang.org/docs/visibility-modifiers.html", "title": "Kotlin · Phạm vi truy cập"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q5", "text": "The ___ keyword is used to call a method from the parent class.", "type": "single", "options": [{"id": "A", "text": "this"}, {"id": "B", "text": "super"}, {"id": "C", "text": "parent"}, {"id": "D", "text": "self"}], "answers": ["B"], "plain": true, "note": "", "explanation": "super.method() gọi phần triển khai của lớp cha từ lớp con; this chỉ đối tượng hiện tại. Khi override một hàm, có thể gọi super để tái sử dụng hành vi cũ rồi thêm hành vi mới.", "references": [{"url": "https://kotlinlang.org/docs/inheritance.html", "title": "Kotlin · Kế thừa"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q6", "text": "A(n) ___ defines properties or methods that a class needs to implement.", "type": "single", "options": [{"id": "A", "text": "Delegate"}, {"id": "B", "text": "Generic type"}, {"id": "C", "text": "Interface"}, {"id": "D", "text": "Subclass"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Interface định nghĩa một hợp đồng gồm các thành viên mà lớp triển khai cần đáp ứng. Interface Kotlin có thể có phần triển khai mặc định của hàm; nó không phải luôn chỉ có tên hàm trống. Nó khác generic, vốn tham số hóa kiểu.", "references": [{"url": "https://kotlinlang.org/docs/interfaces.html", "title": "Kotlin · Interface"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q7", "text": "Which of the following is best represented by a nullable type?", "type": "single", "options": [{"id": "A", "text": "The number of followers (0 or more) in a social media app."}, {"id": "B", "text": "An optional profile picture."}, {"id": "C", "text": "A username that must be at least one character."}, {"id": "D", "text": "A unique ID given to every user."}], "answers": ["B"], "plain": true, "note": "", "explanation": "Ảnh đại diện tùy chọn có thể không tồn tại, nên kiểu nullable như String? cho URL ảnh thể hiện đúng ý nghĩa. Số người theo dõi bằng 0 vẫn là một giá trị Int hợp lệ, không đồng nghĩa dữ liệu vắng mặt.", "references": [{"url": "https://kotlinlang.org/docs/null-safety.html", "title": "Kotlin · Null safety"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q8", "text": "The ___ operator allows you to call a method only if the object is non-null.", "type": "single", "options": [{"id": "A", "text": "."}, {"id": "B", "text": "!!"}, {"id": "C", "text": "?:"}, {"id": "D", "text": "?."}], "answers": ["D"], "plain": true, "note": "", "explanation": "obj?.method() chỉ gọi method khi obj khác null và trả null nếu obj null. !! khẳng định khác null nên có thể gây NullPointerException; ?: cung cấp giá trị thay thế. Mỗi receiver nullable trong chuỗi cần được bảo vệ phù hợp.", "references": [{"url": "https://kotlinlang.org/docs/null-safety.html", "title": "Kotlin · Null safety"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q9", "text": "Which is not true of functions in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A function can be changed to another data type, and vice versa."}, {"id": "B", "text": "A function can be returned from another function."}, {"id": "C", "text": "A function can take another function as a parameter."}, {"id": "D", "text": "A function has a data type, such as (Int) -> Unit ."}], "answers": ["A"], "plain": true, "note": "", "explanation": "Kotlin xem hàm là giá trị có kiểu hàm, có thể truyền làm argument hoặc trả từ hàm khác. Ví dụ (Int) -> Unit nhận Int và không trả giá trị hữu ích. Điều đó không tạo phép chuyển đổi tùy ý giữa hàm và mọi kiểu dữ liệu.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Hàm bậc cao và lambda"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q10", "text": "A function literal is another name for a ___", "type": "single", "options": [{"id": "A", "text": "Function type"}, {"id": "B", "text": "Lambda expression"}, {"id": "C", "text": "Function reference"}, {"id": "D", "text": "Trailing lambda"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Trong các lựa chọn, lambda expression là function literal, như { x: Int -> x + 1 }. Function type mô tả kiểu của giá trị hàm, còn function reference như ::println tham chiếu hàm có sẵn. Kotlin cũng có anonymous function dạng fun(...) { ... }.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Hàm bậc cao và lambda"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 10, "title": "Google · Unit 2 · Pathway 2 · Add a button to an app", "questions": [{"id": "google-u2-p2-q1", "text": "Use a ___ Composable to display an image", "type": "single", "options": [{"id": "A", "text": "Button"}, {"id": "B", "text": "Text"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Icon"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Image là composable dùng để hiển thị Painter hoặc ImageBitmap. Icon thường dùng cho biểu tượng, còn Text để hiển thị chữ. Hãy cung cấp contentDescription phù hợp nếu ảnh truyền tải thông tin cho người dùng.", "references": [{"url": "https://developer.android.com/develop/ui/compose/graphics/images/loading", "title": "Compose · Nạp ảnh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q2", "text": "Alignment.Center centers UI components both horizontally and vertically.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Alignment.Center mô tả căn giữa cả chiều ngang lẫn chiều dọc trong API nhận Alignment, ví dụ contentAlignment của Box. Các API một trục có giá trị riêng như Alignment.CenterHorizontally hoặc CenterVertically.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q3", "text": "Composable functions can store an object in memory using the ___ composable", "type": "single", "options": [{"id": "A", "text": "remember"}, {"id": "B", "text": "Column"}, {"id": "C", "text": "Modifier"}, {"id": "D", "text": "@Composable"}], "answers": ["A"], "plain": true, "note": "", "explanation": "remember giữ kết quả tính tại vị trí đó qua recomposition, tránh tạo lại đối tượng mỗi lần. Nó mất khi composable rời composition và không tự lưu qua Activity recreation; rememberSaveable phù hợp một số state UI cần khôi phục.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q4", "text": "The debugger allows you to inspect variables when code execution has been suspended.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Khi chương trình dừng ở breakpoint, debugger cho xem biến, biểu thức và call stack trong ngữ cảnh đang dừng. Giá trị thuộc thread hoặc frame khác có thể cần chọn đúng frame; debugger không đồng nghĩa chương trình luôn chạy liên tục.", "references": [{"url": "https://developer.android.com/studio/debug", "title": "Android Studio · Debugger"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q5", "text": "By using ___ values in a composable function, variables can be made into observables that schedule a recomposition when their value is changed.", "type": "single", "options": [{"id": "A", "text": "remember"}, {"id": "B", "text": "Modifier"}, {"id": "C", "text": "@Composable"}, {"id": "D", "text": "mutableStateOf"}], "answers": ["D"], "plain": true, "note": "", "explanation": "mutableStateOf tạo một MutableState mà Compose quan sát các lần đọc. Khi value đổi theo chính sách so sánh của State, các vùng đọc nó có thể được lên lịch recomposition. remember chỉ giữ đối tượng; một biến mutable thường không tự trở thành state quan sát được.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q6", "text": "The ___ composable places its children in a vertical sequence.", "type": "single", "options": [{"id": "A", "text": "Row"}, {"id": "B", "text": "Box"}, {"id": "C", "text": "Column"}, {"id": "D", "text": "Modifier"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Column bố trí các con lần lượt theo trục dọc; Row bố trí theo trục ngang. Column không tự có cuộn: cần verticalScroll hoặc dùng LazyColumn cho danh sách phù hợp.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}, "otherSources": [{"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}]}, {"id": "google-u2-p2-q7", "text": "The ___ debugger feature allows you to navigate back up the call stack.", "type": "single", "options": [{"id": "A", "text": "Step over"}, {"id": "B", "text": "Step out"}, {"id": "C", "text": "Step into"}, {"id": "D", "text": "Resume program"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Step out tiếp tục chạy đến khi thoát hàm hiện tại rồi dừng ở caller, giúp đi lên mức gọi phía ngoài. Step into đi vào hàm được gọi, Step over đi qua dòng hiện tại và Resume chạy tiếp đến điểm dừng kế tiếp.", "references": [{"url": "https://developer.android.com/studio/debug", "title": "Android Studio · Debugger"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 11, "title": "Google · Unit 2 · Pathway 3 · Interacting with UI and state", "questions": [{"id": "google-u2-p3-q1", "text": "Jetpack Compose runs your composables for the first time, during ___ it will keep track of the composables that you call to describe your UI.", "type": "single", "options": [{"id": "A", "text": "Initial composition"}, {"id": "B", "text": "Recomposition"}, {"id": "C", "text": "State change"}, {"id": "D", "text": "App termination"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Initial composition là lần Compose chạy các composable ban đầu để tạo mô tả UI và ghi nhận quan hệ giữa chúng. Các cập nhật tiếp theo do dữ liệu liên quan thay đổi thuộc recomposition, không gọi là initial composition nữa.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q2", "text": "The only way to modify a Composition is through recomposition.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Theo mô hình của bài học, thay đổi mô tả UI đã có được thực hiện qua recomposition thay vì sửa cây widget thủ công. Việc state thay đổi là nguyên nhân có thể yêu cầu cập nhật; nó không đồng nghĩa mọi composable đều phải chạy lại.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q3", "text": "___ is when Jetpack Compose re-executes the composables that may have changed in response to data changes.", "type": "single", "options": [{"id": "A", "text": "Initial composition"}, {"id": "B", "text": "Recomposition"}, {"id": "C", "text": "State change"}, {"id": "D", "text": "App termination"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Recomposition thực thi lại các composable cần thiết khi đầu vào hoặc state chúng đọc thay đổi. Compose có thể bỏ qua phần không bị ảnh hưởng; không nên dựa vào việc một composable sẽ chạy đúng số lần cố định.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q4", "text": "___ in an application is any value that can change over time.", "type": "single", "options": [{"id": "A", "text": "State"}, {"id": "B", "text": "value"}, {"id": "C", "text": "valueChange"}, {"id": "D", "text": "StateValue"}], "answers": ["A"], "plain": true, "note": "", "explanation": "State là dữ liệu thay đổi theo thời gian, như nội dung ô nhập, số đếm hoặc mục được chọn. UI nên phản ánh state hiện tại. Không phải mọi biến đều cần là MutableState; lựa chọn cơ chế phụ thuộc nơi quản lý và cách quan sát.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q5", "text": "___ is a pattern of moving state up to make a component stateless.", "type": "single", "options": [{"id": "A", "text": "State change"}, {"id": "B", "text": "State hoisting"}, {"id": "C", "text": "Hoist composition"}, {"id": "D", "text": "Recomposition"}], "answers": ["B"], "plain": true, "note": "", "explanation": "State hoisting chuyển state lên caller và truyền xuống giá trị cùng callback, ví dụ value và onValueChange. Nhờ vậy composable con dễ tái sử dụng và kiểm thử; state có một nguồn quản lý rõ ràng thay vì nhiều bản sao không đồng bộ.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q6", "text": "Which KeyboardAction property is used to move the focus to the next composable?", "type": "single", "options": [{"id": "A", "text": "onDone"}, {"id": "B", "text": "onNext"}, {"id": "C", "text": "onGo"}, {"id": "D", "text": "onSend"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Trong KeyboardActions, onNext nhận hành động IME Next. Khi tự khai báo callback, có thể gọi focusManager.moveFocus(FocusDirection.Down) để chuyển focus phù hợp. Chỉ đặt tên onNext không có nghĩa mọi đoạn callback tùy ý sẽ tự chuyển focus; ImeAction.Next cũng cần cấu hình thích hợp.", "references": [{"url": "https://developer.android.com/develop/ui/compose/touch-input/focus/request-focus", "title": "Compose · Focus"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q7", "text": "Which of the following Kotlin functions is used to round up a Double or Float?", "type": "single", "options": [{"id": "A", "text": "kotlin.math.ceilUp()"}, {"id": "B", "text": "kotlin.math.ceil()"}, {"id": "C", "text": "kotlin.math.roundDown()"}, {"id": "D", "text": "kotlin.math.roundUp()"}], "answers": ["B"], "plain": true, "note": "", "explanation": "kotlin.math.ceil làm tròn về số nguyên gần nhất theo hướng dương vô cùng, nhưng kiểu trả về vẫn là Double hoặc Float tương ứng. Ví dụ ceil(2.1) = 3.0 và ceil(-2.1) = -2.0. Nó khác round và phép đổi .toInt() cắt phần thập phân.", "references": [{"url": "https://kotlinlang.org/api/core/kotlin-stdlib/kotlin.math/ceil.html", "title": "Kotlin · ceil"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q8", "text": "Layout Inspector is a tool in Jetpack Compose that allows you to inspect a Compose layout inside a running app in an emulator or physical device.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Layout Inspector xem cây giao diện của ứng dụng đang chạy trên thiết bị hoặc emulator hỗ trợ, gồm thông tin layout Compose. Nó khác Compose Preview là công cụ xem trước, và khác debugger dùng để dừng/đi từng dòng mã.", "references": [{"url": "https://developer.android.com/studio/debug/layout-inspector", "title": "Layout Inspector"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q9", "text": "UI tests are stored in the ___ directory.", "type": "single", "options": [{"id": "A", "text": "main"}, {"id": "B", "text": "androidTest"}, {"id": "C", "text": "test"}, {"id": "D", "text": "res"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Instrumented UI tests thường đặt tại src/androidTest và chạy trên thiết bị/emulator. Local JVM tests thường ở src/test. Đây là quy ước source set của dự án Android, không phải mọi loại kiểm thử giao diện trong mọi framework đều bắt buộc dùng cùng thư mục.", "references": [{"url": "https://developer.android.com/training/testing/fundamentals", "title": "Kiểm thử Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q10", "text": "Local tests and UI tests should be annotated with the ___ annotation.", "type": "single", "options": [{"id": "A", "text": "@VisibleForTesting"}, {"id": "B", "text": "@Preview"}, {"id": "C", "text": "@Test"}, {"id": "D", "text": "@Composable"}], "answers": ["C"], "plain": true, "note": "", "explanation": "@Test đánh dấu phương thức kiểm thử cho JUnit runner phù hợp. @Preview phục vụ xem trước UI, @Composable đánh dấu hàm Compose và @VisibleForTesting mô tả ý định về phạm vi truy cập, không thay thế @Test.", "references": [{"url": "https://developer.android.com/training/testing/fundamentals", "title": "Kiểm thử Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}]}, {"number": 12, "title": "Google · Unit 3 · Pathway 1 · More Kotlin fundamentals", "questions": [{"id": "google-u3-p1-q1", "text": "Which of the following is a valid way to define a data class in Kotlin?", "type": "single", "options": [{"id": "A", "text": "data class Person(val name: String, val age: Int)"}, {"id": "B", "text": "class Person(val name: String, val age: Int): data"}, {"id": "C", "text": "class Person (val name: String, val age: Int)"}, {"id": "D", "text": "data class Person{val name: String, val age: Int}"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Dùng data class với primary constructor có ít nhất một tham số, và các tham số đó phải là val hoặc var. Kotlin sinh các hàm như equals, hashCode, toString, componentN và copy dựa trên các thuộc tính trong primary constructor.", "references": [{"url": "https://kotlinlang.org/docs/data-classes.html", "title": "Kotlin · Data class"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q2", "text": "When using a sealed class, all direct subclasses must be in the same package.", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Các lớp con trực tiếp của sealed class phải ở cùng package và cùng module; còn có quy tắc bổ sung với multiplatform. Điều này giới hạn tập nhánh để when có thể kiểm tra tính đầy đủ. Không yêu cầu mọi lớp con gián tiếp đều nằm trong cùng một file.", "references": [{"url": "https://kotlinlang.org/docs/sealed-classes.html", "title": "Kotlin · Sealed class"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q3", "text": "When using generics, the generic data type goes inside ___.", "type": "single", "options": [{"id": "A", "text": "[]"}, {"id": "B", "text": "{}"}, {"id": "C", "text": "()"}, {"id": "D", "text": "<>"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Tham số kiểu generic nằm trong < >, như class Box<T> hoặc List<String>. Dấu ( ) dùng cho tham số/argument hàm và { } dùng cho thân khối hoặc lambda. Compiler đôi khi suy ra được argument kiểu nên không cần viết rõ khi gọi.", "references": [{"url": "https://kotlinlang.org/docs/generics.html", "title": "Kotlin · Generics"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q4", "text": "A(n) ___ class is useful when you have a fixed set of values.", "type": "single", "options": [{"id": "A", "text": "enum"}, {"id": "B", "text": "sealed"}, {"id": "C", "text": "data"}, {"id": "D", "text": "inherited"}], "answers": ["A"], "plain": true, "note": "", "explanation": "enum class biểu diễn một tập instance hằng định danh cố định, như Direction.NORTH và SOUTH. sealed class phù hợp một tập loại con có thể mang cấu trúc dữ liệu khác nhau; data class chủ yếu mô hình hóa dữ liệu.", "references": [{"url": "https://kotlinlang.org/docs/enum-classes.html", "title": "Kotlin · Enum"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q5", "text": "To create a list object that has the ability to change its size, you would call ___.", "type": "single", "options": [{"id": "A", "text": "modifiableListOf()"}, {"id": "B", "text": "immutableListOf()"}, {"id": "C", "text": "listOf()"}, {"id": "D", "text": "mutableListOf()"}], "answers": ["D"], "plain": true, "note": "", "explanation": "mutableListOf(...) tạo MutableList có thao tác add/remove để đổi kích thước. listOf(...) cung cấp giao diện List chỉ đọc, không có add/remove qua giao diện đó; “read-only” không nhất thiết chứng minh đối tượng nền bất biến tuyệt đối.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q6", "text": "Which of the following are higher-order functions?", "type": "multi", "options": [{"id": "A", "text": "map"}, {"id": "B", "text": "arrangeBy"}, {"id": "C", "text": "filter"}, {"id": "D", "text": "forEach"}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "map biến đổi mỗi phần tử, filter giữ các phần tử thỏa điều kiện và forEach thực hiện hành động cho từng phần tử; cả ba nhận hàm/lambda làm tham số. arrangeBy không phải hàm chuẩn trong nhóm này; để sắp xếp có sortedBy hoặc sortBy tùy loại collection.", "references": [{"url": "https://kotlinlang.org/docs/collection-transformations.html", "title": "Kotlin · Phép biến đổi collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q7", "text": "Given the following line of code, which of the following commands will print Blue ? (Hint: If you are not sure, try running the code in the Kotlin Playground.)\n\nval colors = listOf(\"Red\", \"Green\", \"Blue\")", "type": "multi", "options": [{"id": "A", "text": "println(colors[2])"}, {"id": "B", "text": "println(colors.get(2))"}, {"id": "C", "text": "println(colors.contains(2))"}, {"id": "D", "text": "println(colors.getOrDefaultValue(index = 2, defaultValue = 10))"}], "answers": ["A", "B"], "plain": true, "note": "", "explanation": "List dùng chỉ số bắt đầu từ 0, nên vị trí 2 là phần tử thứ ba \"Blue\". colors[2] tương đương colors.get(2). contains kiểm tra sự hiện diện của một giá trị chứ không đọc theo chỉ số; getOrDefaultValue trong lựa chọn không phải API List chuẩn đó.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q8", "text": "The programming concept of a class that has only one instance is called a ___.", "type": "single", "options": [{"id": "A", "text": "Uniqueness"}, {"id": "B", "text": "Singleton"}, {"id": "C", "text": "Mono-object"}, {"id": "D", "text": "Lambda"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Singleton là mẫu có một instance được dùng chung. Trong Kotlin, object declaration là cách khai báo singleton quen thuộc; class thông thường vẫn tạo được nhiều instance nếu constructor cho phép. Lambda là giá trị hàm, không phải khái niệm singleton.", "references": [{"url": "https://kotlinlang.org/docs/object-declarations.html", "title": "Kotlin · Singleton"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q9", "text": "Which of the following statements is true regarding sets and maps?", "type": "single", "options": [{"id": "A", "text": "A set must contain distinct values and a map’s keys must be distinct."}, {"id": "B", "text": "A set must contain distinct values and a map’s keys can contain duplicates."}, {"id": "C", "text": "A set can contain duplicate values and a map’s values can contain duplicate values."}, {"id": "D", "text": "A set can contain duplicate values and a map’s keys must be distinct."}], "answers": ["A"], "plain": true, "note": "", "explanation": "Set chứa các phần tử phân biệt; Map có key phân biệt nhưng value có thể lặp. Thêm lại key vào mutable map thường cập nhật value tương ứng, không tạo thêm hai mục có cùng key.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q10", "text": "If you have a variable named records , which is a collection, to determine the number of items it contains, you can call ___.", "type": "single", "options": [{"id": "A", "text": "records.length"}, {"id": "B", "text": "records.quantity"}, {"id": "C", "text": "len(records)"}, {"id": "D", "text": "records.size"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Thuộc tính size cho biết số phần tử của Collection, như list, set hoặc map. length thường dùng cho String hoặc CharSequence. size không phải index cuối: list có 3 phần tử thì index hợp lệ là 0, 1, 2.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 13, "title": "Google · Unit 3 · Pathway 2 · Build a scrollable list", "questions": [{"id": "google-u3-p2-q1", "text": "Adaptive launcher icons for Android apps consist of a foreground and background vector drawable.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Google chấm True theo bài thực hành tạo foreground/background bằng vector drawable. Về API tổng quát, adaptive icon nhận drawable cho các lớp, không bắt buộc tất cả phải là vector. Launcher áp mask lên các lớp; phiên bản mới còn có thể dùng lớp monochrome.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q2", "text": "When building a UI that requires a scrolling list with a variable number of items, which Composable should you use?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Row"}, {"id": "C", "text": "LazyColumn"}, {"id": "D", "text": "Card"}], "answers": ["C"], "plain": true, "note": "", "explanation": "LazyColumn chỉ compose/bố trí các mục cần thiết khi hiển thị, phù hợp danh sách dọc cuộn lớn hoặc có số lượng thay đổi. Column tạo tất cả con và không tự cuộn. Lazy không có nghĩa dữ liệu không cần tải: việc nạp dữ liệu vẫn là trách nhiệm khác.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q3", "text": "What file type is used for the launcher icon foreground and background vectors?", "type": "single", "options": [{"id": "A", "text": ".txt"}, {"id": "B", "text": ".jpg"}, {"id": "C", "text": ".png"}, {"id": "D", "text": ".xml"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Vector drawable được mô tả bằng XML, bao gồm các đường path và màu. PNG/JPG là bitmap chứ không phải định dạng vector XML của Android. adaptive-icon cũng được khai báo bằng XML để tham chiếu các lớp icon.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q4", "text": "Which Composable should you use to create a vertically scrollable grid with an undetermined number of items?", "type": "single", "options": [{"id": "A", "text": "LazyColumn"}, {"id": "B", "text": "LazyVerticalGrid"}, {"id": "C", "text": "LazyHorizontalGrid"}, {"id": "D", "text": "Row"}], "answers": ["B"], "plain": true, "note": "", "explanation": "LazyVerticalGrid hiển thị các ô dạng lưới có cuộn dọc và tạo nội dung theo nhu cầu. LazyHorizontalGrid cuộn ngang, còn LazyColumn là danh sách một chiều dọc. Chọn số cột cố định hoặc adaptive theo yêu cầu thiết kế.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q5", "text": "The Column composable is not a good option for a list of items of unknown quantity because ___.", "type": "single", "options": [{"id": "A", "text": "It can only hold a small, finite number of predefined items"}, {"id": "B", "text": "It arranges items vertically"}, {"id": "C", "text": "It provides scrolling by default without any additional code"}, {"id": "D", "text": "It can add content on demand"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Google chấm phương án đầu trong bản gốc, nhưng diễn đạt rằng Column “chỉ chứa được ít phần tử định sẵn” là giản lược. Column vẫn có thể tạo nội dung từ danh sách động; điểm yếu là tạo tất cả con và không tự cuộn. LazyColumn phù hợp hơn khi danh sách lớn hoặc không biết trước kích thước.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q6", "text": "The ___ method is used to add content to a LazyColumn Composable.", "type": "single", "options": [{"id": "A", "text": "painterResource()"}, {"id": "B", "text": "Modifier.padding()"}, {"id": "C", "text": "items()"}, {"id": "D", "text": "onCreate()"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Trong content DSL của LazyColumn, items(list) hoặc items(count) thêm nhiều mục; item { ... } thêm một mục riêng. Đây không phải Modifier hay hàm nạp ảnh. Dùng key ổn định khi phù hợp giúp giữ state mục khi danh sách thay đổi.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q7", "text": "Which Composable arranges items horizontally?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Card"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Row"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Row bố trí các phần tử theo chiều ngang; dùng horizontalArrangement và verticalAlignment để điều chỉnh. Card là container Material, không tự mang ý nghĩa xếp mọi con thành một hàng trong tất cả API.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 14, "title": "Google · Unit 3 · Pathway 3 · Build beautiful apps", "questions": [{"id": "google-u3-p3-q1", "text": "Animations in your Android app can:", "type": "single", "options": [{"id": "A", "text": "Add visual cues about what's going on in your app."}, {"id": "B", "text": "Add a polished look to your app."}, {"id": "C", "text": "Help the user see what changed."}, {"id": "D", "text": "All of the above."}], "answers": ["D"], "plain": true, "note": "", "explanation": "Animation có thể cho biết hành động đang diễn ra, làm rõ thay đổi UI và tạo chuyển động mượt hơn, nên chọn All of the above. Chuyển động vẫn cần có mục đích và cân nhắc khả năng tiếp cận; thêm nhiều animation không tự bảo đảm UX tốt.", "references": [{"url": "https://developer.android.com/develop/ui/compose/animation/customize", "title": "Compose · Animation"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q2", "text": "Spring animation is based on:", "type": "single", "options": [{"id": "A", "text": "Start and end values over the specified duration."}, {"id": "B", "text": "Damping ratio and stiffness."}, {"id": "C", "text": "Snapshot values specified at different timestamps."}, {"id": "D", "text": "Interpolation between two keyframe values."}], "answers": ["B"], "plain": true, "note": "", "explanation": "Spring là mô hình vật lý điều khiển chủ yếu bởi dampingRatio và stiffness, không phải chỉ thời lượng cố định. Damping ảnh hưởng dao động/tắt dần, stiffness ảnh hưởng độ cứng và nhịp đáp ứng. tween và keyframes là các cách mô tả chuyển động khác.", "references": [{"url": "https://developer.android.com/develop/ui/compose/animation/customize", "title": "Compose · Animation"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q3", "text": "Spring animation is a physics-based animation driven by spring force.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Spring animation mô phỏng lực lò xo đưa giá trị về mục tiêu. Khi đổi mục tiêu giữa chừng, nó có thể tiếp tục dựa trên trạng thái/vận tốc hiện tại, khác cách nội suy chỉ dựa trên mốc thời gian cố định.", "references": [{"url": "https://developer.android.com/develop/ui/compose/animation/customize", "title": "Compose · Animation"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q6", "text": "You can only have one @Preview composable", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Có thể tạo nhiều hàm @Preview hoặc áp dụng nhiều preview để xem nhiều kích thước, theme và cấu hình. Preview phục vụ công cụ Android Studio, không phải giới hạn số màn hình trong ứng dụng. Hàm preview gọi UI Compose phù hợp với các yêu cầu của công cụ.", "references": [{"url": "https://developer.android.com/develop/ui/compose/tooling/previews", "title": "Compose · Preview"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q11", "text": "TalkBack allows a user to navigate an app using switches instead of the touchscreen.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "TalkBack là screen reader, đọc nội dung và hỗ trợ điều hướng bằng phản hồi giọng nói/cử chỉ. Dùng công tắc bên ngoài để điều khiển là Switch Access. Hai công cụ hỗ trợ các nhu cầu khác nhau nên phát biểu gán chức năng switch cho TalkBack là sai.", "references": [{"url": "https://support.google.com/accessibility/android/answer/6122836", "title": "Google · Switch Access"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q12", "text": "Which attribute allows TalkBack to speak a meaningful representation of an image or icon?", "type": "single", "options": [{"id": "A", "text": "elevation"}, {"id": "B", "text": "shape"}, {"id": "C", "text": "contentDescription"}, {"id": "D", "text": "style"}], "answers": ["C"], "plain": true, "note": "", "explanation": "contentDescription giúp TalkBack nói ý nghĩa ảnh/icon có thông tin hoặc hành động. Hãy mô tả tác dụng như “Mở tìm kiếm” thay vì chỉ “biểu tượng kính lúp”. Với ảnh trang trí, đặt mô tả null khi phù hợp để tránh thông tin gây nhiễu.", "references": [{"url": "https://developer.android.com/develop/ui/compose/accessibility/semantics", "title": "Compose · Accessibility"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}]}];
